/**
 * The highest number a project has ever issued. Archived issues keep their
 * number, and a moved-away issue has left its number behind, so the recorded
 * counter is consulted alongside the rows and the larger one wins.
 */
function highestIssuedNumber(orgId: OrgId, projectId: ProjectId): number {
  const counter = getDb()
    .select({ value: issueNumberCounters.lastNumber })
    .from(issueNumberCounters)
    .where(
      and(
        orgPredicate(issueNumberCounters.orgId, orgId),
        eq(issueNumberCounters.projectId, projectId),
      ),
    )
    .get();
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return Math.max(counter?.value ?? 0, row?.value ?? 0);
}

/** Records that `projectId` has issued up to `number`. Never moves backwards. */
function recordIssuedNumber(
  orgId: OrgId,
  projectId: ProjectId,
  number: number,
): void {
  getDb()
    .insert(issueNumberCounters)
    .values({ orgId, projectId, lastNumber: number })
    .onConflictDoUpdate({
      target: issueNumberCounters.projectId,
      set: {
        lastNumber: sql`max(${issueNumberCounters.lastNumber}, excluded.last_number)`,
      },
    })
    .run();
}

/** Next per-project issue number. Read-only: `insertIssue` records what it takes. */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return highestIssuedNumber(orgId, projectId) + 1;
}

