/**
 * Files an issue under `toProjectId` with that project's next number. The
 * number it leaves behind is retired first: the source project's counter is
 * brought up to date before the row moves, so the number is never issued
 * there again. Everything else on the row, and the labels, comments and
 * attachments that point at it, is left as it is.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issue: Issue,
  toProjectId: ProjectId,
): Promise<Issue> {
  recordIssuedNumber(orgId, issue.projectId, highestIssuedNumber(orgId, issue.projectId));
  const number = highestIssuedNumber(orgId, toProjectId) + 1;

  const row = getDb()
    .update(issues)
    .set({
      projectId: toProjectId,
      number,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issue.id)))
